import 'dart:convert';
import 'package:http/http.dart' as http;

void main() async {
  try {
    var response1 = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts/1')); // Make the first HTTP GET request
    var response2 = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts/2')); // Make the second HTTP GET request
    if (response1.statusCode == 200 && response2.statusCode == 200) { // Check if both responses are successful
      var data1 = jsonDecode(response1.body); // Decode the JSON response of the first request
