#import <Foundation/Foundation.h>

int main(int argc, const char * argv[]) {
    @autoreleasepool {

        //Accept input string from user
        char input[100];
        printf("Enter a string: ");
        scanf("%[^\n]",input);

        //Remove spaces and punctuation marks
        NSMutableString *strippedString = [NSMutableString stringWithCapacity:input.length];
        NSCharacterSet *validCharSet = [NSCharacterSet characterSetWithCharactersInString:@"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"];
        for (NSUInteger I = 0; I < input.length; i++) {
            unichar c = [input characterAtIndex:i];
            if ([validCharSet characterIsMember:c]) {
                [strippedString appendFormat:@"%C", c];
            }
        }
        NSString *inputString = strippedString.lowercaseString;

        //Check if input string is a palindrome or not
        BOOL isPalindrome = YES;
        NSUInteger length = inputString.length;
        for (NSUInteger I = 0; I < length/2; i++) {
            if ([inputString characterAtIndex:i] != [inputString characterAtIndex:length-1-i]) {
                isPalindrome = NO;
                break;
            }
        }

        //Display result
        if (isPalindrome) {
            printf("%s is a palindrome.\n", input);
        } else {
            printf("%s is not a palindrome.\n", input);
        }

    }
    return 0;
}
```

Here is an example implementation for a linked list class with basic operations:

```
public class LinkedList {

    // Node class for the linked list
    private class Node {
        int data;
        Node next;

        public Node(int data) {
            this.data = data;
            next = null;
        }
    }

    private Node head; // Head of the linked list

    public LinkedList() {
        head = null;
    }

    // Add a new node to the end of the linked list
    public void add(int data) {
        Node newNode = new Node(data);
        if (head == null) {
            head = newNode;
        } else {
            Node current = head;
            while (current.next != null) {
                current = current.next;
            }
            current.next = newNode;
        }
    }

    // Remove the first occurrence of a node with the given data
    public void remove(int data) {
        if (head == null) {
            return;
        }
        if (head.data == data) {
            head = head.next;
            return;
        }
        Node current = head;
        while (current.next != null) {
            if (current.next.data == data) {
                current.next = current.next.next;
                return;
            }
            current = current.next;
        }
    }

    // Check if the linked list contains a node with the given data
    public boolean contains(int data) {
        Node current = head;
        while (current != null) {
            if (current.data == data) {
                return true;
            }
            current = current.next;
        }
        return false;
    }

    // Get the size of the linked list
    public int size() {
        int count = 0;
        Node current = head;
        while (current != null) {
            count++;
            current = current.next;
        }
        return count;
    }
}
```

Here is how you can use this class:

```
LinkedList myList = new LinkedList();
myList.add(1);
myList.add(2);
myList.add(3);
System.out.println("Size of the linked list: " + myList.size()); // Output: Size of the linked list: 3
System.out.println("Contains 2? " + myList.contains(2)); // Output: Contains 2? true
myList.remove(2);
System.out.println("Size of the linked list after removing 2: " + myList.size()); // Output: Size of the linked list after removing 2: 2
```

Here is an example Java program that implements the quicksort algorithm using the Hoare partition scheme:

```java
import java.util.Arrays;

public class QuickSort {

    public static void quicksort(int[] arr, int start, int end) {
        if (start < end) {
            // Partition the array and get the pivot index
            int pivotIdx = partition(arr, start, end);
            // Recursively sort the left and right sub-arrays
            quicksort(arr, start, pivotIdx - 1);
            quicksort(arr, pivotIdx + 1, end);
        }
    }

    public static int partition(int[] arr, int start, int end) {
        // Choose the first element as the pivot
        int pivot = arr[start];
        int I = start - 1;
        int j = end + 1;
        while (true) {
            // Find the next element from the left that is >= the pivot
            do {
                i++;
            } while (arr[i] < pivot);
            // Find the next element from the right that is <= the pivot
            do {
                j--;
            } while (arr[j] > pivot);
            // If the pointers have converged, return the pivot index
            if (i >= j) {
                return j;
            }
            // Swap the elements at I and j
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    public static void main(String[] args) {
        int[] arr = {10, 7, 8, 9, 1, 5};
        int n = arr.length;
        quicksort(arr, 0, n-1);
        System.out.println(Arrays.toString(arr));
    }
}
```

The `quicksort` function takes an array `arr`, a starting index `start`, and an ending index `end` as arguments. If the sub-array from `start` to `end` contains more than one element, it partitions the sub-array using the `partition` function, and recursively sorts the resulting left and right sub-arrays.

The `partition` function takes an array `arr`, a starting index `start`, and an ending index `end` as arguments, and returns the index of the pivot element after partitioning the sub-array from `start` to `end`. It starts by choosing the first element as the pivot, and maintains two pointers `i` and `j` that scan the sub-array from left and right respectively. The function repeatedly moves `i` and `j` towards each other, swapping the elements at `i` and `j` if necessary to maintain the invariant that all elements to the left of `i` are less than or equal to the pivot, and all elements to the right of `j` are greater than or equal to the pivot. The function returns the index of the final `j` pointer, which is now the pivot index.

In the `main` function, we initialize an input array `arr`, call the `quicksort` function to sort the array, and output the sorted array using the `Arrays.toString` function.

This implementation uses the Hoare partition scheme, where the pivot is generally chosen to be the first element of the sub-array. It ensures that the pivot is correctly placed (i.e., all elements to the left of the pivot are less than or equal to it, and all elements to the right are greater than or equal to it) by swapping elements that are on the wrong side of the pivot. The Hoare partition scheme is more efficient than the Lomuto partition scheme (which chooses the last element as the pivot), and is more commonly used in practice.

Here's a clear and concise Kotlin function that takes in an array of integers and returns the maximum value found in the array:

```
/**
 * Finds the maximum value in a given array of integers.
 *
 * @param numbers An array of integers.
 * @return The maximum value found in the array.
 */
fun findMax(numbers: Array<Int>): Int {
    var max = Int.MIN_VALUE
    for (number in numbers) {
        if (number > max) {
            max = number
        }
    }
    return max
}
```

This function takes in an array of integers `numbers` and returns the maximum value found in the array. It starts by initializing `max` to the smallest possible integer value using `Int.MIN_VALUE`. Then it loops through each number in the array and checks if it's greater than the current `max` value. If it is, then it sets `max` equal to that number.

Finally, it returns the maximum value found in the array.

The function is well-documented with a clear description of what it does and what parameters it takes in. The function name `findMax` is also clear and concise, indicating what the function does. The function adheres to best coding practices by using a for loop to iterate over the array, and by using `if` statements to check conditions.

Here is a sample code in Java that calculates the area and perimeter of a circle:

```
import java.util.Scanner;

public class Circle {
    public static void main(String[] args) {

        final double PI = 3.14;
        double radius, area, perimeter;

        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the radius of the circle: ");
        radius = scanner.nextDouble();

        area = PI * radius * radius;
        perimeter = 2 * PI * radius;

        System.out.println("Area of the circle is: " + area);
        System.out.println("Perimeter of the circle is: " + perimeter);

    }
}
```

In this program, we first define a constant `PI` which is the ratio of the circumference of a circle to its diameter. We then ask the user to enter the radius of the circle, which is stored in the variable `radius`.

We calculate the area of the circle using the formula `area = PI * radius * radius`, and store it in the variable `area`. Similarly, we calculate the perimeter of the circle using the formula `perimeter = 2 * PI * radius`, and store it in the variable `perimeter`.

Finally, we display the calculated area and perimeter of the circle using the `System.out.println()` method.

